/**
 * The Phase 3 robot city dataset and the rules that keep it coherent.
 *
 * `robot-city.json` is one local artifact: the road graph, the presentation blocks and
 * the landmark placements. It is generated by `tools/build_city_dataset.mjs` from a
 * fixed seed, and every consumer (renderer, selection helpers, and later the router)
 * reads this same document, so there is no second source of truth.
 *
 * Coordinates stay local to the scene: plane XZ, Y up, metres. Nothing here stores a
 * geographic coordinate, and nothing here loads a map service.
 */

import type { AssetId } from '../scene/assets';

import rawCity from './robot-city.json';

/** Comparison constant for every "is this zero?" question, in metres. */
export const EPSILON_M = 1e-9;
/** Pick radius for a node, in metres. Two separate constants on purpose. */
export const SNAP_NODE_MAX_RADIUS_M = 12.0;
/** Pick radius for an edge, in metres. */
export const SNAP_EDGE_MAX_RADIUS_M = 12.0;

export interface CityPoint {
  x: number;
  y: number;
  z: number;
}

export type CityNodeKind = 'DEPOT' | 'JUNCTION' | 'DELIVERY';

export interface CityNode {
  nodeId: string;
  kind: CityNodeKind;
  position: CityPoint;
  label?: string;
}

export interface CityEdge {
  edgeId: string;
  fromNodeId: string;
  toNodeId: string;
  bidirectional: boolean;
  lengthMeters: number;
  speedLimitKph: number;
  /**
   * Presentation only. The polyline starts and ends exactly on the node positions, so a
   * junction never shows a gap, and it never feeds a distance or a route.
   */
  visualSplineControlPoints: readonly CityPoint[];
}

export type CityBlockKind = 'BUILT' | 'PARK' | 'PLAZA';

export interface CityBuildingPlacement {
  x: number;
  z: number;
  rotationYDegrees: number;
  scale: number;
}

export interface CityBlock {
  blockId: string;
  kind: CityBlockKind;
  center: { x: number; z: number };
  size: { x: number; z: number };
  buildings: readonly CityBuildingPlacement[];
}

export interface CityLandmark {
  landmarkId: string;
  nodeId: string;
  assetId: AssetId;
  rotationYDegrees: number;
  scale: number;
}

export interface CityPresentation {
  groundMarginMeters: number;
  routeWidthMeters: number;
  roadWidthMetersBySpeedKph: Readonly<Record<string, number>>;
  blockPadHeightMeters: number;
  roadSurfaceHeightMeters: number;
  routeSurfaceHeightMeters: number;
  buildingAssetId: AssetId;
}

export interface CityDataset {
  cityId: string;
  graphVersion: number;
  capturedAt: string;
  generator: string;
  seed: number;
  units: 'meters';
  coordinateSystem: 'local-xz-up-y';
  bounds: { minX: number; maxX: number; minZ: number; maxZ: number };
  presentation: CityPresentation;
  nodes: readonly CityNode[];
  edges: readonly CityEdge[];
  blocks: readonly CityBlock[];
  landmarks: readonly CityLandmark[];
}

export const CITY_DATASET = rawCity as unknown as CityDataset;

const NODE_ID_PATTERN = /^N-[0-9]{3}$/;
const EDGE_ID_PATTERN = /^E-N[0-9]{3}-N[0-9]{3}$/;
const CITY_ID_PATTERN = /^[a-z0-9-]{3,32}$/;

const NODE_KEYS = ['nodeId', 'kind', 'position', 'label'];
const EDGE_KEYS = [
  'edgeId',
  'fromNodeId',
  'toNodeId',
  'bidirectional',
  'lengthMeters',
  'speedLimitKph',
  'visualSplineControlPoints',
];
const NODE_KINDS: readonly CityNodeKind[] = ['DEPOT', 'JUNCTION', 'DELIVERY'];
const BLOCK_KINDS: readonly CityBlockKind[] = ['BUILT', 'PARK', 'PLAZA'];

/**
 * Token fragments for the map-service guard. They are assembled at runtime so this
 * module does not contain the literal tokens it rejects, which is what lets the guard
 * scan the whole city source tree including itself.
 */
const FORBIDDEN_MAP_REFERENCE_FRAGMENTS: readonly (readonly string[])[] = [
  ['lat', 'itude'],
  ['long', 'itude'],
  ['lat', 'lng'],
  ['leaf', 'let'],
  ['map', 'box'],
  ['open', 'street', 'map'],
  ['os', 'rm'],
  ['goo', 'gle ma', 'ps'],
  ['bing ma', 'ps'],
  ['here ma', 'ps'],
  ['map', 'tiler'],
  ['tile ', 'server'],
];

export function distanceXz(a: { x: number; z: number }, b: { x: number; z: number }): number {
  return Math.hypot(a.x - b.x, a.z - b.z);
}

/** Canonical edge id: lexicographically smaller node first, separators removed. */
export function canonicalEdgeId(firstNodeId: string, secondNodeId: string): string {
  const [low, high] = [firstNodeId, secondNodeId].sort();
  return `E-${low.replace('-', '')}-${high.replace('-', '')}`;
}

export interface RoadNetwork {
  dataset: CityDataset;
  nodes: ReadonlyMap<string, CityNode>;
  edges: ReadonlyMap<string, CityEdge>;
  depotNodeId: string;
  /** Delivery-capable nodes in lexicographic order: the only nodes that take orders. */
  deliveryNodeIds: readonly string[];
  nodeIds: readonly string[];
  edgeIds: readonly string[];
}

export function createRoadNetwork(dataset: CityDataset = CITY_DATASET): RoadNetwork {
  const nodes = new Map<string, CityNode>();
  for (const node of dataset.nodes) nodes.set(node.nodeId, node);
  const edges = new Map<string, CityEdge>();
  for (const edge of dataset.edges) edges.set(edge.edgeId, edge);
  const depot = dataset.nodes.find((node) => node.kind === 'DEPOT');
  if (!depot) {
    throw new Error('the city dataset has no DEPOT node');
  }
  return {
    dataset,
    nodes,
    edges,
    depotNodeId: depot.nodeId,
    deliveryNodeIds: dataset.nodes
      .filter((node) => node.kind === 'DELIVERY')
      .map((node) => node.nodeId)
      .sort(),
    nodeIds: [...nodes.keys()].sort(),
    edgeIds: [...edges.keys()].sort(),
  };
}

export function roadWidthMetersFor(
  edge: CityEdge,
  presentation: CityPresentation = CITY_DATASET.presentation,
): number {
  const width = presentation.roadWidthMetersBySpeedKph[String(edge.speedLimitKph)];
  if (typeof width !== 'number' || !(width > 0)) {
    throw new Error(`no road width is declared for ${edge.speedLimitKph} km/h`);
  }
  return width;
}

/** Undirected adjacency, used by reachability. Every MVP edge is bidirectional. */
function adjacency(network: RoadNetwork): Map<string, { edgeId: string; nodeId: string }[]> {
  const result = new Map<string, { edgeId: string; nodeId: string }[]>();
  for (const nodeId of network.nodes.keys()) result.set(nodeId, []);
  for (const edge of network.edges.values()) {
    result.get(edge.fromNodeId)?.push({ edgeId: edge.edgeId, nodeId: edge.toNodeId });
    if (edge.bidirectional) {
      result.get(edge.toNodeId)?.push({ edgeId: edge.edgeId, nodeId: edge.fromNodeId });
    }
  }
  for (const neighbours of result.values()) {
    neighbours.sort((a, b) => (a.edgeId < b.edgeId ? -1 : a.edgeId > b.edgeId ? 1 : 0));
  }
  return result;
}

export function roadAdjacency(network: RoadNetwork) {
  return adjacency(network);
}

/**
 * Nodes reachable from `startNodeId` without crossing a blocked edge. A blocked edge is
 * excluded in both directions, which is the rule the MVP fixes for barriers.
 */
export function reachableNodeIds(
  network: RoadNetwork,
  startNodeId: string,
  blockedEdgeIds: Iterable<string> = [],
): Set<string> {
  const blocked = new Set(blockedEdgeIds);
  const neighbours = adjacency(network);
  const seen = new Set<string>([startNodeId]);
  const queue = [startNodeId];
  while (queue.length > 0) {
    const nodeId = queue.shift() as string;
    for (const neighbour of neighbours.get(nodeId) ?? []) {
      if (blocked.has(neighbour.edgeId) || seen.has(neighbour.nodeId)) continue;
      seen.add(neighbour.nodeId);
      queue.push(neighbour.nodeId);
    }
  }
  return seen;
}

export interface CityValidationOptions {
  minNodes?: number;
  maxNodes?: number;
}

function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

function unknownKeys(value: object, allowed: readonly string[]): string[] {
  return Object.keys(value).filter((key) => !allowed.includes(key));
}

/**
 * Contract self-check for the city dataset. It returns an empty list when the document
 * is coherent and a human readable problem list otherwise, so a broken dataset fails a
 * test instead of a user session.
 */
export function validateCityDataset(
  dataset: CityDataset = CITY_DATASET,
  options: CityValidationOptions = {},
): string[] {
  const problems: string[] = [];
  const minNodes = options.minNodes ?? 40;
  const maxNodes = options.maxNodes ?? 80;

  if (!CITY_ID_PATTERN.test(dataset.cityId)) problems.push(`cityId ${dataset.cityId} is invalid`);
  if (!Number.isInteger(dataset.graphVersion) || dataset.graphVersion < 1) {
    problems.push('graphVersion must be a positive integer');
  }
  if (dataset.units !== 'meters') problems.push(`units must be meters, received ${dataset.units}`);
  if (dataset.coordinateSystem !== 'local-xz-up-y') {
    problems.push(`coordinateSystem must be local-xz-up-y, received ${dataset.coordinateSystem}`);
  }
  if (!Number.isInteger(dataset.seed)) problems.push('seed must be an integer');

  const bounds = dataset.bounds;
  if (bounds.minX >= bounds.maxX || bounds.minZ >= bounds.maxZ) {
    problems.push('bounds must be a positive area');
  }

  if (dataset.nodes.length < minNodes || dataset.nodes.length > maxNodes) {
    problems.push(
      `the dataset must declare between ${minNodes} and ${maxNodes} nodes, found ${dataset.nodes.length}`,
    );
  }

  const nodes = new Map<string, CityNode>();
  for (const node of dataset.nodes) {
    if (!NODE_ID_PATTERN.test(node.nodeId)) problems.push(`node id ${node.nodeId} is invalid`);
    if (nodes.has(node.nodeId)) problems.push(`duplicate node id ${node.nodeId}`);
    nodes.set(node.nodeId, node);
    if (!NODE_KINDS.includes(node.kind)) problems.push(`${node.nodeId}: unknown kind ${node.kind}`);
    for (const key of unknownKeys(node, NODE_KEYS)) {
      problems.push(`${node.nodeId}: unexpected property ${key}`);
    }
    const position = node.position;
    if (unknownKeys(position, ['x', 'y', 'z']).length > 0) {
      problems.push(`${node.nodeId}: position has unexpected properties`);
    }
    if (!isFiniteNumber(position.x) || !isFiniteNumber(position.y) || !isFiniteNumber(position.z)) {
      problems.push(`${node.nodeId}: position is not finite`);
    }
    if (position.y !== 0) {
      problems.push(`${node.nodeId}: the MVP city is flat, so y must be 0`);
    }
    if (position.x < bounds.minX || position.x > bounds.maxX) {
      problems.push(`${node.nodeId}: x is outside the declared bounds`);
    }
    if (position.z < bounds.minZ || position.z > bounds.maxZ) {
      problems.push(`${node.nodeId}: z is outside the declared bounds`);
    }
  }

  const depots = dataset.nodes.filter((node) => node.kind === 'DEPOT');
  if (depots.length !== 1) problems.push(`exactly one DEPOT is required, found ${depots.length}`);
  const deliveryNodes = dataset.nodes.filter((node) => node.kind === 'DELIVERY');
  if (deliveryNodes.length === 0) problems.push('at least one DELIVERY node is required');

  const edges = new Map<string, CityEdge>();
  const pairs = new Set<string>();
  for (const edge of dataset.edges) {
    if (!EDGE_ID_PATTERN.test(edge.edgeId)) problems.push(`edge id ${edge.edgeId} is invalid`);
    if (edges.has(edge.edgeId)) problems.push(`duplicate edge id ${edge.edgeId}`);
    edges.set(edge.edgeId, edge);
    for (const key of unknownKeys(edge, EDGE_KEYS)) {
      problems.push(`${edge.edgeId}: unexpected property ${key}`);
    }
    const from = nodes.get(edge.fromNodeId);
    const to = nodes.get(edge.toNodeId);
    if (!from || !to) {
      problems.push(`${edge.edgeId}: endpoint does not exist`);
      continue;
    }
    if (edge.fromNodeId === edge.toNodeId) problems.push(`${edge.edgeId}: self loop`);
    if (!(edge.fromNodeId < edge.toNodeId)) {
      problems.push(`${edge.edgeId}: fromNodeId must be the lexicographically smaller node`);
    }
    if (edge.edgeId !== canonicalEdgeId(edge.fromNodeId, edge.toNodeId)) {
      problems.push(`${edge.edgeId}: id is not the canonical pair of its endpoints`);
    }
    const pair = `${edge.fromNodeId}|${edge.toNodeId}`;
    if (pairs.has(pair)) problems.push(`${edge.edgeId}: duplicate node pair ${pair}`);
    pairs.add(pair);
    if (edge.bidirectional !== true) {
      problems.push(`${edge.edgeId}: every MVP edge is bidirectional`);
    }
    const expectedLength = distanceXz(from.position, to.position);
    if (!isFiniteNumber(edge.lengthMeters) || Math.abs(edge.lengthMeters - expectedLength) > 1e-9) {
      problems.push(
        `${edge.edgeId}: lengthMeters ${edge.lengthMeters} is not the XZ distance ${expectedLength}`,
      );
    }
    if (!(edge.speedLimitKph > 0)) problems.push(`${edge.edgeId}: speedLimitKph must be positive`);
    if (!(String(edge.speedLimitKph) in dataset.presentation.roadWidthMetersBySpeedKph)) {
      problems.push(`${edge.edgeId}: no road width for ${edge.speedLimitKph} km/h`);
    }

    const spline = edge.visualSplineControlPoints;
    if (!Array.isArray(spline) || spline.length < 2) {
      problems.push(`${edge.edgeId}: the visual spline needs at least two control points`);
      continue;
    }
    const first = spline[0];
    const last = spline[spline.length - 1];
    if (first.x !== from.position.x || first.z !== from.position.z || first.y !== 0) {
      problems.push(`${edge.edgeId}: the visual spline must start on ${edge.fromNodeId}`);
    }
    if (last.x !== to.position.x || last.z !== to.position.z || last.y !== 0) {
      problems.push(`${edge.edgeId}: the visual spline must end on ${edge.toNodeId}`);
    }
    for (const control of spline) {
      if (!isFiniteNumber(control.x) || !isFiniteNumber(control.y) || !isFiniteNumber(control.z)) {
        problems.push(`${edge.edgeId}: the visual spline has a non-finite control point`);
        break;
      }
      if (control.y !== 0) {
        problems.push(`${edge.edgeId}: the visual spline must stay on the ground plane`);
        break;
      }
    }
    // The bow is decoration: a control point may not wander far from the logical line,
    // or a cosmetic edit would silently become a geometry change.
    const maxDeviation = edge.lengthMeters * 0.05;
    for (const control of spline) {
      const deviation = pointToSegmentDistanceXz(control, from.position, to.position);
      if (deviation > maxDeviation) {
        problems.push(
          `${edge.edgeId}: a visual control point deviates ${deviation} m, more than 5% of the edge`,
        );
        break;
      }
    }
  }

  for (const nodeId of new Set([...nodes.keys()])) {
    if (!dataset.edges.some((edge) => edge.fromNodeId === nodeId || edge.toNodeId === nodeId)) {
      problems.push(`${nodeId}: the node has no incident edge`);
    }
  }

  const blockIds = new Set<string>();
  const blockBuildings = new Set<string>();
  for (const block of dataset.blocks) {
    if (blockIds.has(block.blockId)) problems.push(`duplicate block id ${block.blockId}`);
    blockIds.add(block.blockId);
    if (!BLOCK_KINDS.includes(block.kind)) problems.push(`${block.blockId}: unknown kind`);
    if (!(block.size.x > 0) || !(block.size.z > 0)) {
      problems.push(`${block.blockId}: block size must be positive`);
    }
    if (!isFiniteNumber(block.center.x) || !isFiniteNumber(block.center.z)) {
      problems.push(`${block.blockId}: block centre is not finite`);
    }
    if (block.kind !== 'BUILT' && block.buildings.length > 0) {
      problems.push(`${block.blockId}: only BUILT blocks carry buildings`);
    }
    for (const building of block.buildings) {
      if (!(building.scale > 0)) problems.push(`${block.blockId}: building scale must be positive`);
      if (Math.abs(building.x - block.center.x) > block.size.x / 2) {
        problems.push(`${block.blockId}: a building is outside the block on the x axis`);
      }
      if (Math.abs(building.z - block.center.z) > block.size.z / 2) {
        problems.push(`${block.blockId}: a building is outside the block on the z axis`);
      }
      const key = `${building.x}:${building.z}`;
      if (blockBuildings.has(key)) problems.push(`two buildings share the position ${key}`);
      blockBuildings.add(key);
    }
  }

  const landmarkIds = new Set<string>();
  for (const landmark of dataset.landmarks) {
    if (landmarkIds.has(landmark.landmarkId)) {
      problems.push(`duplicate landmark id ${landmark.landmarkId}`);
    }
    landmarkIds.add(landmark.landmarkId);
    if (!nodes.has(landmark.nodeId)) {
      problems.push(`${landmark.landmarkId}: node ${landmark.nodeId} does not exist`);
    }
    if (!(landmark.scale > 0)) problems.push(`${landmark.landmarkId}: scale must be positive`);
  }
  if (depots.length === 1 && !dataset.landmarks.some((landmark) => landmark.nodeId === depots[0].nodeId)) {
    problems.push('the depot node has no landmark');
  }

  const presentation = dataset.presentation;
  for (const key of [
    'groundMarginMeters',
    'routeWidthMeters',
    'blockPadHeightMeters',
    'roadSurfaceHeightMeters',
    'routeSurfaceHeightMeters',
  ] as const) {
    if (!(presentation[key] >= 0)) problems.push(`presentation.${key} must not be negative`);
  }
  if (presentation.routeSurfaceHeightMeters <= presentation.roadSurfaceHeightMeters) {
    problems.push('the route surface must sit above the road surface');
  }

  const network: RoadNetwork = {
    dataset,
    nodes,
    edges,
    depotNodeId: depots[0]?.nodeId ?? '',
    deliveryNodeIds: deliveryNodes.map((node) => node.nodeId).sort(),
    nodeIds: [...nodes.keys()].sort(),
    edgeIds: [...edges.keys()].sort(),
  };
  if (depots.length === 1) {
    const reachable = reachableNodeIds(network, depots[0].nodeId);
    for (const nodeId of network.deliveryNodeIds) {
      if (!reachable.has(nodeId)) {
        problems.push(`${nodeId}: delivery node is unreachable from the depot on the unblocked graph`);
      }
    }
    for (const nodeId of network.nodeIds) {
      if (!reachable.has(nodeId)) problems.push(`${nodeId}: node is unreachable from the depot`);
    }
  }

  return problems;
}

/** Distance from a point to a segment in the XZ plane; `t` is clamped to [0, 1]. */
export function pointToSegmentDistanceXz(
  point: { x: number; z: number },
  start: { x: number; z: number },
  end: { x: number; z: number },
): number {
  const dx = end.x - start.x;
  const dz = end.z - start.z;
  const lengthSquared = dx * dx + dz * dz;
  if (lengthSquared <= EPSILON_M) return distanceXz(point, start);
  const rawT = ((point.x - start.x) * dx + (point.z - start.z) * dz) / lengthSquared;
  const t = Math.min(1, Math.max(0, rawT));
  return distanceXz(point, { x: start.x + t * dx, z: start.z + dz * t });
}

/**
 * Guard against the map-service shortcuts the MVP forbids: geographic coordinates,
 * tiles, an external map URL or a routing service. It is a text scan, so it can run
 * over the dataset and over the source tree in a test.
 */
/** Map-service tokens found in a text, without the absolute-URL rule. */
export function forbiddenMapTokensFound(source: string): string[] {
  const lower = source.toLowerCase();
  const problems: string[] = [];
  for (const fragments of FORBIDDEN_MAP_REFERENCE_FRAGMENTS) {
    const token = fragments.join('');
    if (token.length > 0 && lower.includes(token)) {
      problems.push(`forbidden map reference ${fragments.join('+')}`);
    }
  }
  return problems;
}

export function scanForForbiddenMapReferences(source: string): string[] {
  const problems = forbiddenMapTokensFound(source);
  if (/https?:\/\//i.test(source)) {
    problems.push('forbidden absolute URL');
  }
  return problems;
}

export function cityBuildingCount(dataset: CityDataset = CITY_DATASET): number {
  return dataset.blocks.reduce((total, block) => total + block.buildings.length, 0);
}
